bool _messageChanged(Message a, Message b) {
  if (a.runtimeType != b.runtimeType) return true;
  return switch (a) {
    TextMessage textA => textA.text != (b as TextMessage).text,
    CustomMessage customA =>
      customA.metadata?.toString() !=
