/// A [FakeChatService] with a controllable above-count and tap recording.
class _PagingService extends FakeChatService {
  int? above;
  int? below;
  int? total;
  bool loading = false;
  int loadCalls = 0;
  List<FaChatMessage> msgs = const [];

  @override
